"""Minimal JSON API.

Exposes the two endpoints the container/compose health checks depend on:
  /healthz  liveness  - process is up, no downstream I/O
  /readyz   readiness - Postgres and Redis are reachable
"""

from __future__ import annotations

import os

from flask import Flask, jsonify

app = Flask(__name__)

STATE = "starting"


def _check_postgres() -> bool:
    import psycopg2  # imported lazily so /healthz never needs the driver

    try:
        with psycopg2.connect(os.environ["DATABASE_URL"], connect_timeout=3) as conn:
            with conn.cursor() as cur:
                cur.execute("SELECT 1")
                cur.fetchone()
        return True
    except Exception:
        app.logger.exception("postgres readiness check failed")
        return False


def _check_redis() -> bool:
    import redis

    try:
        return bool(redis.Redis.from_url(os.environ["REDIS_URL"], socket_timeout=3).ping())
    except Exception:
        app.logger.exception("redis readiness check failed")
        return False


@app.get("/healthz")
def healthz():
    return jsonify(status="ok")


@app.get("/readyz")
def readyz():
    pg, rd = _check_postgres(), _check_redis()
    payload = {"status": "ok" if (pg and rd) else "degraded", "postgres": pg, "redis": rd}
    return jsonify(payload), (200 if (pg and rd) else 503)


if __name__ == "__main__":
    # Local convenience only; containers run gunicorn (see Dockerfile CMD).
    app.run(host="127.0.0.1", port=5000)

user nginx;
worker_processes auto;
worker_rlimit_nofile 2048;
pid /var/run/nginx.pid;

events {
    worker_connections 1024;
    multi_accept on;
}

http {
    include       /etc/nginx/mime.types;
    default_type  application/json;

    # Do not advertise the nginx version in responses or error pages.
    server_tokens off;

    log_format main '$remote_addr - $remote_user [$time_iso8601] "$request" '
                    '$status $body_bytes_sent "$http_referer" '
                    '"$http_user_agent" rt=$request_time ut=$upstream_response_time';
    access_log /var/log/nginx/access.log main;
    error_log  /var/log/nginx/error.log warn;

    sendfile        on;
    tcp_nopush      on;
    tcp_nodelay     on;

    # Keep connections to the app alive; the timeout must stay below gunicorn's
    # keepalive (5s in gunicorn.conf.py) so nginx is the side that recycles.
    keepalive_timeout 15s;
    keepalive_requests 1000;

    client_max_body_size 1m;      # JSON API: reject oversized bodies early
    client_body_timeout 10s;
    client_header_timeout 10s;
    send_timeout 30s;

    # Compress JSON responses only; do not compress already-compressed types.
    gzip on;
    gzip_proxied any;
    gzip_min_length 256;
    gzip_types application/json application/problem+json text/plain;
    gzip_vary on;

    # One request per client IP, small burst: cheap abuse brake for a small API.
    limit_req_zone $binary_remote_addr zone=api_limit:10m rate=20r/s;
    limit_conn_zone $binary_remote_addr zone=api_conn:10m;

    upstream api_upstream {
        server api:5000 max_fails=3 fail_timeout=10s;
        keepalive 32;
    }

    # Docker's embedded DNS; combined with the variable in proxy_pass below,
    # nginx resolves `api` at request time instead of failing at startup when
    # the api container is not up yet.
    resolver 127.0.0.11 valid=10s ipv6=off;

    server {
        listen 80 default_server;
        server_name _;

        limit_req zone=api_limit burst=40 nodelay;
        limit_conn api_conn 50;

        # nginx's own liveness endpoint: never touches the upstream.
        location = /nginx-healthz {
            access_log off;
            add_header Content-Type text/plain always;
            return 200 "ok\n";
        }

        location / {
            # Variable form forces runtime DNS resolution (see `resolver`).
            set $upstream_api http://api_upstream;
            proxy_pass $upstream_api;

            proxy_http_version 1.1;

            # Connection upgrade handling (harmless for plain JSON, needed if a
            # websocket endpoint is added later).
            proxy_set_header Connection "";

            # --- Proxy headers: the app must see the original request ---
            proxy_set_header Host              $host;
            proxy_set_header X-Real-IP         $remote_addr;
            proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header X-Forwarded-Host  $host;
            proxy_set_header X-Forwarded-Port  $server_port;
            proxy_set_header X-Request-ID      $request_id;

            # --- Timeouts: fail fast, do not hold workers on a stalled app ---
            proxy_connect_timeout 5s;
            proxy_send_timeout    30s;
            proxy_read_timeout    30s;

            # Retry only when the request was not yet delivered upstream.
            proxy_next_upstream error timeout http_502 http_503 http_504;
            proxy_next_upstream_tries 2;

            # Do not let upstream redirects rewrite the public hostname.
            proxy_redirect off;

            # Only these upstream status codes are cached by clients via
            # Cache-Control emitted by the app; nothing is cached here.
            proxy_buffering on;
            proxy_buffer_size 8k;
            proxy_buffers 16 8k;
        }

        # Health endpoints bypass rate limiting so probes are never throttled.
        location = /healthz {
            set $upstream_api http://api_upstream;
            proxy_pass $upstream_api;
            proxy_http_version 1.1;
            proxy_set_header Host $host;
            proxy_set_header Connection "";
            proxy_connect_timeout 2s;
            proxy_read_timeout 5s;
            access_log off;
        }

        location = /readyz {
            set $upstream_api http://api_upstream;
            proxy_pass $upstream_api;
            proxy_http_version 1.1;
            proxy_set_header Host $host;
            proxy_set_header Connection "";
            proxy_connect_timeout 2s;
            proxy_read_timeout 5s;
            access_log off;
        }
    }
}

